package com.nexusid.dao;
import com.nexusid.db.Database;import java.sql.*;import java.util.*;
public class MerchantDAO{
 public List<String> products(long merchantUserId)throws SQLException{List<String>o=new ArrayList<>();String q="SELECT mp.id,o.name,mp.name,mp.price,mp.stock,mp.status FROM merchant_products mp JOIN merchant_outlets o ON o.id=mp.outlet_id JOIN merchants m ON m.id=o.merchant_id JOIN users u ON u.id=m.user_id AND u.role='MERCHANT' AND u.status='ACTIVE' WHERE m.user_id=? ORDER BY o.name,mp.name";try(Connection c=Database.getConnection();PreparedStatement p=c.prepareStatement(q)){p.setLong(1,merchantUserId);try(ResultSet r=p.executeQuery()){while(r.next())o.add("#"+r.getLong(1)+" | "+r.getString(2)+" | "+r.getString(3)+" | ₹"+r.getBigDecimal(4)+" | Stock: "+r.getInt(5)+" | "+r.getString(6));}}return o;}
 public void updateProduct(long merchantUserId,long productId,java.math.BigDecimal price,int stock)throws SQLException{if(price==null||price.compareTo(java.math.BigDecimal.ZERO)<0)throw new IllegalArgumentException("Price cannot be negative.");if(stock<0)throw new IllegalArgumentException("Stock cannot be negative.");String q="UPDATE merchant_products mp JOIN merchant_outlets o ON o.id=mp.outlet_id JOIN merchants m ON m.id=o.merchant_id JOIN users u ON u.id=m.user_id AND u.role='MERCHANT' AND u.status='ACTIVE' SET mp.price=?,mp.stock=? WHERE mp.id=? AND m.user_id=?";try(Connection c=Database.getConnection();PreparedStatement p=c.prepareStatement(q)){p.setBigDecimal(1,price);p.setInt(2,stock);p.setLong(3,productId);p.setLong(4,merchantUserId);if(p.executeUpdate()==0)throw new SQLException("Product not found for this merchant.");}}


 public List<String> summary(long merchantUserId)throws SQLException{List<String> out=new ArrayList<>();String[] labels={"Active products","Total orders","Open orders","Completed orders","Gross completed sales"};String[] queries={"SELECT COUNT(*) FROM merchant_products mp JOIN merchant_outlets o ON o.id=mp.outlet_id JOIN merchants m ON m.id=o.merchant_id JOIN users u ON u.id=m.user_id AND u.role='MERCHANT' AND u.status='ACTIVE' WHERE m.user_id=? AND mp.status='ACTIVE'","SELECT COUNT(*) FROM merchant_orders mo JOIN merchants m ON m.id=mo.merchant_id JOIN users u ON u.id=m.user_id AND u.role='MERCHANT' AND u.status='ACTIVE' WHERE m.user_id=?","SELECT COUNT(*) FROM merchant_orders mo JOIN merchants m ON m.id=mo.merchant_id JOIN users u ON u.id=m.user_id AND u.role='MERCHANT' AND u.status='ACTIVE' WHERE m.user_id=? AND mo.status IN ('PAID','PROCESSING','READY')","SELECT COUNT(*) FROM merchant_orders mo JOIN merchants m ON m.id=mo.merchant_id JOIN users u ON u.id=m.user_id AND u.role='MERCHANT' AND u.status='ACTIVE' WHERE m.user_id=? AND mo.status='COLLECTED'","SELECT COALESCE(SUM(mo.total_amount),0) FROM merchant_orders mo JOIN merchants m ON m.id=mo.merchant_id JOIN users u ON u.id=m.user_id AND u.role='MERCHANT' AND u.status='ACTIVE' WHERE m.user_id=? AND mo.status='COLLECTED'"};try(Connection c=Database.getConnection()){for(int i=0;i<queries.length;i++)try(PreparedStatement p=c.prepareStatement(queries[i])){p.setLong(1,merchantUserId);try(ResultSet r=p.executeQuery()){r.next();String value=i==4?"₹"+r.getBigDecimal(1):String.valueOf(r.getLong(1));out.add(labels[i]+": "+value);}}}return out;}
 public List<String> recentSales(long merchantUserId)throws SQLException{List<String> out=new ArrayList<>();String q="SELECT mo.reference_id,mo.created_at,mo.total_amount,mo.status FROM merchant_orders mo JOIN merchants m ON m.id=mo.merchant_id JOIN users u ON u.id=m.user_id AND u.role='MERCHANT' AND u.status='ACTIVE' WHERE m.user_id=? ORDER BY mo.created_at DESC LIMIT 30";try(Connection c=Database.getConnection();PreparedStatement p=c.prepareStatement(q)){p.setLong(1,merchantUserId);try(ResultSet r=p.executeQuery()){while(r.next())out.add(r.getString(1)+" | "+r.getTimestamp(2)+" | ₹"+r.getBigDecimal(3)+" | "+r.getString(4));}}return out;}
}
